import unittest
from candidate import mean_absolute_deviation

class TestMeanAbsoluteDeviation(unittest.TestCase):
    def test_mean_absolute_deviation_normal_case(self):
        self.assertAlmostEqual(mean_absolute_deviation([1.0, 2.0, 3.0, 4.0]), 1.0)

    def test_mean_absolute_deviation_single_element(self):
        self.assertAlmostEqual(mean_absolute_deviation([1.0]), 0.0)

    def test_mean_absolute_deviation_empty_list(self):
        with self.assertRaises(ZeroDivisionError):
            mean_absolute_deviation([])

    def test_mean_absolute_deviation_none_input(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation(None)

    def test_mean_absolute_deviation_non_numeric_input(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation(['a', 'b', 'c'])

    def test_mean_absolute_deviation_mixed_types_input(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation([1.0, 'a', 3.0])

    def test_mean_absolute_deviation_negative_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([-1.0, -2.0, -3.0, -4.0]), 1.0)

    def test_mean_absolute_deviation_large_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([100.0, 200.0, 300.0, 400.0]), 100.0)

    def test_mean_absolute_deviation_decimal_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([1.5, 2.5, 3.5, 4.5]), 1.0)

if __name__ == '__main__':
    unittest.main()
